import{$,$$,status,download,copy,escape,bytes}from'./common.js';import{pdfjs,PDFDocument,StandardFonts,rgb}from'./vendor.js';pdfjs.GlobalWorkerOptions.workerSrc='./pdf.worker.min.mjs';
let files=[],mode='extract',currentPDF=null,order=[],busy=false,selectionRevision=0;const canvas=$('#pdfPreview');
function setBusy(value){busy=value;$('#process').disabled=value;$('#sample').disabled=value;$('#file').disabled=value;$$('[data-mode]').forEach(b=>b.disabled=value)}
function list(){const host=$('#files');host.innerHTML='';files.forEach((file,i)=>{const li=document.createElement('li');li.innerHTML=`<span>${escape(file.name)}<br><small>${bytes(file.data.byteLength)}</small></span><button data-up aria-label="Move document up" ${i===0?'disabled':''}>↑</button><button data-down aria-label="Move document down" ${i===files.length-1?'disabled':''}>↓</button><button data-remove aria-label="Remove document">×</button>`;li.querySelector('[data-up]').onclick=()=>{[files[i-1],files[i]]=[files[i],files[i-1]];list();loadFirst()};li.querySelector('[data-down]').onclick=()=>{[files[i],files[i+1]]=[files[i+1],files[i]];list();loadFirst()};li.querySelector('[data-remove]').onclick=()=>{files.splice(i,1);list();loadFirst()};host.append(li)})}
async function loadFirst(){const r=++selectionRevision;currentPDF=null;order=[];$('#pages').replaceChildren();$('#markdown').value='';canvas.getContext('2d').clearRect(0,0,canvas.width,canvas.height);if(!files.length){status('Choose a PDF to get started.');return}try{const pdf=await pdfjs.getDocument({data:files[0].data.slice()}).promise;if(r!==selectionRevision)return;currentPDF=pdf;order=Array.from({length:pdf.numPages},(_,i)=>i);const page=await pdf.getPage(1);const viewport=page.getViewport({scale:.8});canvas.width=viewport.width;canvas.height=viewport.height;await page.render({canvasContext:canvas.getContext('2d'),viewport}).promise;pageList();status(pdf.numPages+' pages loaded.');if(mode==='extract')await extract()}catch(e){status('Could not open this PDF: '+e.message,true)}}
function pageList(){$('#pages').replaceChildren();order.forEach((n,i)=>{const li=document.createElement('li');li.innerHTML=`<span>Page ${n+1}</span><button data-up aria-label="Move page ${n+1} up" ${i===0?'disabled':''}>↑</button><button data-down aria-label="Move page ${n+1} down" ${i===order.length-1?'disabled':''}>↓</button><button data-remove aria-label="Remove page ${n+1}" ${order.length===1?'disabled':''}>×</button>`;li.querySelector('[data-up]').onclick=()=>{[order[i-1],order[i]]=[order[i],order[i-1]];pageList()};li.querySelector('[data-down]').onclick=()=>{[order[i],order[i+1]]=[order[i+1],order[i]];pageList()};li.querySelector('[data-remove]').onclick=()=>{order.splice(i,1);pageList()};$('#pages').append(li)})}
async function extract(){if(!currentPDF)throw Error('Choose a readable PDF first.');const results=[];let characters=0;for(let n=1;n<=currentPDF.numPages;n++){const page=await currentPDF.getPage(n),text=await page.getTextContent();const items=text.items.filter(x=>x.str?.trim());const sizes=items.map(x=>Math.abs(x.transform[3])).sort((a,b)=>a-b);const base=sizes[Math.floor(sizes.length*.4)]||12;const groups=[];for(const item of items){const y=Math.round(item.transform[5]/3)*3;let line=groups.find(l=>Math.abs(l.y-y)<4);if(!line){line={y,size:0,items:[]};groups.push(line)}line.items.push(item);line.size=Math.max(line.size,Math.abs(item.transform[3]))}groups.sort((a,b)=>b.y-a.y);const lines=groups.map(l=>{const s=l.items.sort((a,b)=>a.transform[4]-b.transform[4]).map(x=>x.str).join(' ').trim();characters+=s.length;return(l.size>=base*1.5?'# ':l.size>=base*1.2?'## ':'')+s});results.push((currentPDF.numPages>1?'<!-- Page '+n+' -->\n\n':'')+lines.join('\n\n'))}$('#markdown').value=results.join('\n\n---\n\n');status(characters?`Extracted ${currentPDF.numPages} page${currentPDF.numPages===1?'':'s'}. Review the editable Markdown before using it.`:'No selectable text found. This PDF may be scanned and needs OCR.',!characters)}
$('#file').onchange=async e=>{try{const selected=[...e.target.files];if(selected.some(f=>f.size>30*1048576))throw Error('Choose PDFs under 30 MB each.');files=await Promise.all(selected.map(async f=>({name:f.name,data:new Uint8Array(await f.arrayBuffer())})));list();await loadFirst()}catch(e){status(e.message,true)}};
async function sample(){setBusy(true);try{const doc=await PDFDocument.create();const regular=await doc.embedFont(StandardFonts.Helvetica),bold=await doc.embedFont(StandardFonts.HelveticaBold);const contents=[['A little everyday magic','A short guide to building useful software','Start with the outcome','The best tools make a small task feel effortless.','Give people a clear next step and a useful result.','Build with care','Readable interfaces, fast feedback and sensible defaults.','Make it easy to try, easy to understand and easy to share.'],['Notes from the studio','Tech Buzzs / sample document','Keep the useful parts','Listen to the problem before choosing the technology.','A small, polished tool can make a big difference.','What comes next','Review this Markdown draft and make it your own.','This PDF was generated locally in your browser.']];for(const lines of contents){const p=doc.addPage([520,660]);p.drawRectangle({x:0,y:0,width:520,height:660,color:rgb(.98,.97,.94)});p.drawText('DOCUMENT DESK / SAMPLE',{x:40,y:612,size:10,font:bold,color:rgb(.65,.35,.2)});let y=560;lines.forEach((line,i)=>{const size=i===0?24:i===2||i===5?17:11;p.drawText(line,{x:40,y,size,font:i===0||i===2||i===5?bold:regular,color:rgb(.18,.2,.25)});y-=i===0?35:i===1?65:i===4?70:28});p.drawText('Tech Buzzs · browser-local sample',{x:40,y:40,size:9,font:regular,color:rgb(.5,.5,.5)})}files=[{name:'studio-notes.pdf',data:await doc.save()}];list();await loadFirst()}catch(e){status(e.message,true)}finally{setBusy(false)}}$('#sample').onclick=sample;
$$('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;$$('[data-mode]').forEach(x=>x.classList.toggle('active',x===b));$('#extractView').hidden=mode!=='extract';$('#organizeView').hidden=mode!=='reorder';$('#resultTitle').textContent=mode==='extract'?'From document to draft':mode==='merge'?'Combine your documents':'Put pages in their place';$('#process').textContent=mode==='extract'?'Extract Markdown':mode==='merge'?'Download merged PDF':'Download reordered PDF';['copy','download','text'].forEach(id=>$('#'+id).hidden=mode!=='extract');$('#modeHint').textContent=mode==='extract'?'Best for PDFs with selectable text. Scanned pages need OCR, which this version does not include.':mode==='merge'?'Choose multiple PDFs. Use the document arrows to set their order.':'Use the page arrows to reorder pages, or remove pages you do not need.';status('');if(mode==='extract'&&currentPDF)extract().catch(e=>status(e.message,true))});
$('#process').onclick=async()=>{if(busy)return;setBusy(true);try{if(!files.length)throw Error('Choose at least one PDF first.');if(mode==='extract'){await extract();return}const output=await PDFDocument.create();if(mode==='merge'){for(const file of files){const source=await PDFDocument.load(file.data);const pages=await output.copyPages(source,source.getPageIndices());pages.forEach(p=>output.addPage(p))}}else{if(!order.length)throw Error('Choose a readable PDF first.');const source=await PDFDocument.load(files[0].data);const pages=await output.copyPages(source,order);pages.forEach(p=>output.addPage(p))}download(new Blob([await output.save()],{type:'application/pdf'}),mode==='merge'?'merged.pdf':'reordered.pdf');status('Your PDF is ready.')}catch(e){status(e.message,true)}finally{setBusy(false)}};$('#copy').onclick=()=>copy($('#markdown').value);$('#download').onclick=()=>{if(!$('#markdown').value.trim()){status('Extract some text first.',true);return}download(new Blob([$('#markdown').value],{type:'text/markdown'}),'document.md')};$('#text').onclick=()=>{if(!$('#markdown').value.trim()){status('Extract some text first.',true);return}download(new Blob([$('#markdown').value.replace(/^#{1,6}\s/gm,'').replace(/^<!--.*-->$/gm,'').replace(/^---$/gm,'')],{type:'text/plain'}),'document.txt')};sample();
